11	#ifndef ATVOSS_TILE_ASCENDC_MATH_H
12	#define ATVOSS_TILE_ASCENDC_MATH_H
13	#include "lib/math/power.h"
14	#include "common/arch.h"
15	#include "tile_shape.h"
16	
17	namespace Atvoss::Tile {
18	
19	/*!
20	 * \brief dst[i] = src0[i] + src1[i]
21	 * \param[in] src0, Input LocalTensor
22	 * \param[in] src1, Input LocalTensor
23	 * \param[out] dst, Output LocalTensor
24	 */
25	template <typename OperationShape, typename T>
26	__aicore__ inline void AddAssign(
27	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src0, const AscendC::LocalTensor<T>& src1,
28	    OperationShape& operationShape)
29	{
30	    AscendC::Add(dst, src0, src1, operationShape.axis0);
31	}
32	
33	/*!
34	 * \brief dst[i] = src[i] + scalar
35	 * \param[in] src, Input LocalTensor
36	 * \param[in] scalar, Input scalar
37	 * \param[out] dst, Output LocalTensor
38	 */
39	template <typename OperationShape, typename T>
40	__aicore__ inline void AddsAssign(
41	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, T scalar, OperationShape& operationShape)
42	{
43	    AscendC::Adds(dst, src, scalar, operationShape.axis0);
44	}
45	
46	/*!
47	 * \brief dst[i] = src0[i] - src1[i]
48	 * \param[in] src0, Input LocalTensor
49	 * \param[in] src1, Input LocalTensor
50	 * \param[out] dst, Output LocalTensor
51	 */
52	template <typename OperationShape, typename T>
53	__aicore__ inline void SubAssign(
54	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src0, const AscendC::LocalTensor<T>& src1,
55	    OperationShape& operationShape)
56	{
57	    AscendC::Sub(dst, src0, src1, operationShape.axis0);
58	}
59	
60	#if _ATVOSS_ARCH35_
61	/*!
62	 * \brief dst[i] = src[i] - scalar
63	 * \param[in] src, Input LocalTensor
64	 * \param[in] scalar, Input scalar
65	 * \param[out] dst, Output LocalTensor
66	 */
67	template <typename OperationShape, typename T>
68	__aicore__ inline void SubsAssign(
69	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, T scalar, OperationShape& operationShape)
70	{
71	    AscendC::Subs(dst, src, scalar, operationShape.axis0);
72	}
73	
74	/*!
75	 * \brief dst[i] = scalar - src[i]
76	 * \param[in] src, Input LocalTensor
77	 * \param[in] scalar, Input scalar
78	 * \param[out] dst, Output LocalTensor
79	 */
80	template <typename OperationShape, typename T>
81	__aicore__ inline void SubsAssign(
82	    AscendC::LocalTensor<T>& dst, T scalar, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
83	{
84	    AscendC::Subs(dst, scalar, src, operationShape.axis0);
85	}
86	#endif
87	
88	/*!
89	 * \brief dst[i] = src0[i] * src1[i]
90	 * \param[in] src0, Input LocalTensor
91	 * \param[in] src1, Input LocalTensor
92	 * \param[out] dst, Output LocalTensor
93	 */
94	template <typename OperationShape, typename T>
95	__aicore__ inline void MulAssign(
96	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src0, const AscendC::LocalTensor<T>& src1,
97	    OperationShape& operationShape)
98	{
99	    AscendC::Mul(dst, src0, src1, operationShape.axis0);
100	}
101	
102	/*!
103	 * \brief dst[i] = src[i] * src1
104	 * \param[in] src, Input LocalTensor
105	 * \param[in] src1, Input scalar
106	 * \param[out] dst, Output LocalTensor
107	 */
108	template <typename OperationShape, typename T>
109	__aicore__ inline void MulsAssign(
110	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, T src1, OperationShape& operationShape)
111	{
112	    AscendC::Muls(dst, src, src1, operationShape.axis0);
113	}
114	
115	/*!
116	 * \brief dst[i] = src0[i] / src1[i]
117	 * \param[in] src0, Input LocalTensor
118	 * \param[in] src1, Input LocalTensor
119	 * \param[out] dst, Output LocalTensor
120	 */
121	template <typename OperationShape, typename T>
122	__aicore__ inline void DivAssign(
123	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src0, const AscendC::LocalTensor<T>& src1,
124	    OperationShape& operationShape)
125	{
126	    AscendC::Div(dst, src0, src1, operationShape.axis0);
127	}
128	
129	#if _ATVOSS_ARCH35_
130	/*!
131	 * \brief dst[i] = src[i] / scalar
132	 * \param[in] src, Input LocalTensor
133	 * \param[in] scalar, Input scalar
134	 * \param[out] dst, Output LocalTensor
135	 */
136	template <typename OperationShape, typename T>
137	__aicore__ inline void DivsAssign(
138	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, T scalar, OperationShape& operationShape)
139	{
140	    AscendC::Divs(dst, src, scalar, operationShape.axis0);
141	}
142	
143	/*!
144	 * \brief dst[i] = scalar / src[i]
145	 * \param[in] src, Input LocalTensor
146	 * \param[in] scalar, Input scalar
147	 * \param[out] dst, Output LocalTensor
148	 */
149	template <typename OperationShape, typename T>
150	__aicore__ inline void DivsAssign(
151	    AscendC::LocalTensor<T>& dst, T scalar, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
152	{
153	    AscendC::Divs(dst, scalar, src, operationShape.axis0);
154	}
155	#endif
156	
157	/*!
158	 * \brief dst[i] = src[i] / scalarValue
159	 * \param[in] src, Input LocalTensor
160	 * \param[out] dst, Output LocalTensor
161	 */
162	template <typename OperationShape, auto scalarValue, typename T>
163	__aicore__ inline void DivsAssign(
164	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
165	{
166	    T src1 = T{1} / scalarValue;
167	    AscendC::Muls(dst, src, src1, operationShape.axis0);
168	}
169	
170	/*!
171	 * \brief dst[i] = exp(src[i])
172	 * \param[in] src, Input LocalTensor
173	 * \param[out] dst, Output LocalTensor
174	 */
175	template <typename OperationShape, typename T>
176	__aicore__ inline void ExpAssign(
177	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
178	{
179	    AscendC::Exp(dst, src, operationShape.axis0);
180	}
181	
182	/*!
183	 * \brief dst[i] = abs(src[i])
184	 * \param[in] src, Input LocalTensor
185	 * \param[out] dst, Output LocalTensor
186	 */
187	template <typename OperationShape, typename T>
188	__aicore__ inline void AbsAssign(
189	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
190	{
191	    AscendC::Abs(dst, src, operationShape.axis0);
192	}
193	
194	/*!
195	 * \brief dst[i] = sqrt(src[i])
196	 * \param[in] src, Input LocalTensor
197	 * \param[out] dst, Output LocalTensor
198	 */
199	template <typename OperationShape, typename T>
200	__aicore__ inline void SqrtAssign(
201	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
202	{
203	    AscendC::Sqrt(dst, src, operationShape.axis0);
204	}
205	
206	/*!
207	 * \brief dst[i] = power(src[i])
208	 * \param[in] src, Input LocalTensor
209	 * \param[out] dst, Output LocalTensor
210	 */
211	template <typename OperationShape, auto scalarValue, typename T>
212	__aicore__ inline void PowerAssign(
213	    AscendC::LocalTensor<T>& dst, const AscendC::LocalTensor<T>& src, OperationShape& operationShape)
214	{
215	    AscendC::Power(dst, src, T{scalarValue}, operationShape.axis0);
216	}
217	
218	/*!
219	 * \brief dst[i] = cast(src[i])
220	 * \param[in] src, Input LocalTensor
221	 * \param[out] dst, Output LocalTensor
222	 */
223	template <typename OperationShape, CastMode castMode, typename T1, typename T2>
224	__aicore__ inline void CastAssign(
225	    AscendC::LocalTensor<T1>& dst, const AscendC::LocalTensor<T2>& src, OperationShape& operationShape)
226	{
227	    if constexpr (castMode == CastMode::CAST_NONE) {
228	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, operationShape.axis0);
229	    } else if constexpr (castMode == CastMode::CAST_RINT) {
230	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_RINT, operationShape.axis0);
231	    } else if constexpr (castMode == CastMode::CAST_FLOOR) {
232	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_FLOOR, operationShape.axis0);
233	    } else if constexpr (castMode == CastMode::CAST_CEIL) {
234	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_CEIL, operationShape.axis0);
235	    } else if constexpr (castMode == CastMode::CAST_ROUND) {
236	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_ROUND, operationShape.axis0);
237	    } else if constexpr (castMode == CastMode::CAST_TRUNC) {
238	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_TRUNC, operationShape.axis0);
239	    } else if constexpr (castMode == CastMode::CAST_ODD) {
240	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_ODD, operationShape.axis0);
241	    }
242	}
243	
244	using OperationShape = Atvoss::Layout::OperationShape;
245	
246	/*!
247	 * \brief Add calculation based on the expression
248	 * \param[in] args, Input LocalTensor & output LocalTensor
249	 * \param[in] localVars, Temp LocalTensor
250	 * \param[in] tail, Length of calculation data
251	 * \return Add expression
252	 */
253	template <typename T, typename U>
254	struct Evaluator<OpAdd<T, U>> {
255	    using Type =
256	        decltype(Add(std::declval<typename Evaluator<T>::Type>(), std::declval<typename Evaluator<U>::Type>()));
257	
258	    template <typename Context>
259	    __aicore__ inline auto operator()(const OpAdd<T, U>& op, Context& context) const
260	    {
261	        return Add(Evaluator<T>{}(op.GetLhs(), context), Evaluator<U>{}(op.GetRhs(), context));
262	    }
263	};
264	
265	/*!
266	 * \brief Add calculation based on the expression
267	 * \param[in] args, Input LocalTensor & output LocalTensor
268	 * \param[in] localVars, Temp LocalTensor
269	 * \param[in] tail, Length of calculation data
270	 * \return Add expression
271	 */
272	template <typename T, typename U, typename V>
273	struct Evaluator<OpAssign<T, OpAdd<U, V>>> {
274	    using Type = void;
275	
276	    template <typename Context>
277	    __aicore__ inline auto operator()(const OpAssign<T, OpAdd<U, V>>& op, Context& context) const
278	    {
279	        using Dtype = Dtype_t<T>;
280	        OperationShape operationShape = GetShape<Operation::Unary>(context.argsTensors);
281	        static_assert(
282	            !std::is_scalar_v<typename U::Type> || !std::is_scalar_v<typename V::Type>,
283	            "OpAdd's inputs not accepts all scalar types");
284	        if constexpr (std::is_scalar_v<typename U::Type>) {
285	            return Atvoss::Tile::AddsAssign<OperationShape, Dtype>(
286	                Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
287	                Evaluator<V>{}(op.GetRhs().GetRhs(), context).GetUbTensor(),
288	                Evaluator<U>{}(op.GetRhs().GetLhs(), context), operationShape);
289	        } else if constexpr (std::is_scalar_v<typename V::Type>) {
290	            return Atvoss::Tile::AddsAssign<OperationShape, Dtype>(
291	                Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
292	                Evaluator<U>{}(op.GetRhs().GetLhs(), context).GetUbTensor(),
293	                Evaluator<V>{}(op.GetRhs().GetRhs(), context), operationShape);
294	        } else {
295	            return Atvoss::Tile::AddAssign<OperationShape, Dtype>(
296	                Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
297	                Evaluator<U>{}(op.GetRhs().GetLhs(), context).GetUbTensor(),
298	                Evaluator<V>{}(op.GetRhs().GetRhs(), context).GetUbTensor(), operationShape);
299	        }
300	    }
301	};
302	
303	/*!
304	 * \brief Sub calculation based on the expression
305	 * \param[in] args, Input LocalTensor & output LocalTensor
306	 * \param[in] localVars, Temp LocalTensor
307	 * \param[in] tail, Length of calculation data
308	 * \return Sub expression
309	 */
310	template <typename T, typename U, typename V>
311	struct Evaluator<OpAssign<T, OpSub<U, V>>> {
312	    using Type = void;
313	
314	    template <typename Context>
315	    __aicore__ inline auto operator()(const OpAssign<T, OpSub<U, V>>& op, Context& context) const
316	    {
317	        using Dtype = Dtype_t<T>;
318	        OperationShape operationShape = GetShape<Operation::Unary>(context.argsTensors);
319	#if _ATVOSS_ARCH35_
320	        static_assert(
321	            !std::is_scalar_v<typename U::Type> || !std::is_scalar_v<typename V::Type>,
322	            "OpSub's inputs not accepts all scalar types");
323	        if constexpr (std::is_scalar_v<typename U::Type>) {
324	            return Atvoss::Tile::SubsAssign<OperationShape, Dtype>(
325	                Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(), Evaluator<U>{}(op.GetRhs().GetLhs(), context),
326	                Evaluator<V>{}(op.GetRhs().GetRhs(), context).GetUbTensor(), operationShape);
327	        } else if constexpr (std::is_scalar_v<typename V::Type>) {
328	            return Atvoss::Tile::SubsAssign<OperationShape, Dtype>(
329	                Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
330	                Evaluator<U>{}(op.GetRhs().GetLhs(), context).GetUbTensor(),
331	                Evaluator<V>{}(op.GetRhs().GetRhs(), context), operationShape);
332	        } else {
333	            return Atvoss::Tile::SubAssign<OperationShape, Dtype>(
334	                Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
335	                Evaluator<U>{}(op.GetRhs().GetLhs(), context).GetUbTensor(),
336	                Evaluator<V>{}(op.GetRhs().GetRhs(), context).GetUbTensor(), operationShape);
337	        }
338	#else
339	        return Atvoss::Tile::SubAssign<OperationShape, Dtype>(
340	            Evaluator<T>{}(op.GetLhs(), context).GetUbTensor(),
341	            Evaluator<U>{}(op.GetRhs().GetLhs(), context).GetUbTensor(),
342	            Evaluator<V>{}(op.GetRhs().GetRhs(), context).GetUbTensor(), operationShape);
343	#endif
344	    }
345	};
346	
347	/*!
348	 * \brief Mul calculation based on the expression
