29	template <typename T>
30	struct OpCopy;
31	
32	using Atvoss::Util::TypeList;
33	
34	enum class ParamUsage
35	{
36	    IN,
37	    OUT,
38	    IN_OUT,
39	};
40	/*--------------------------------------------------------------------------------------------------------------------*/
41	/*!
42	 * Expression: Type for a basic "expression".  If T is trivial (as it should normally
43	 * be), Expression<T> is trivially copy-constructible and trivially move-
44	 * constructible, but is not trivially assignable.  Objects of the same
45	 * Expression type cannot be assigned, because the data member is const.
46	 * Objects of different Expression types can be assigned, but it will
47	 * result in a new Expression object (and is not a "normal" assignment).
48	 */
49	template <typename T>
50	struct Expression {
51	    static_assert(!std::is_rvalue_reference_v<T>, "[ERROR]: [Atvoss][Expression] Rvalue references cannot be stored");
52	    using Type = T;
53	    using RetType = typename std::conditional_t<std::is_scalar_v<T>, Util::RetTypeWrapper<T>, T>::RetType;
54	    using TensorType = typename std::conditional_t<std::is_scalar_v<T>, Util::TensorTypeWrapper<T>, T>::TensorType;
55	
56	    T const data{};
57	
58	    template <typename U>
59	    [[nodiscard]] constexpr auto operator=(Expression<U> u);
60	};
61	
62	// Let T deduce to value type or lvalue reference type
63	template <typename T>
64	Expression(T&& value) -> Expression<T>;
65	
66	template <typename T>
67	using IsExpression = Util::IsSpecializationOf<Expression, T>;
68	
69	template <typename T>
70	inline constexpr bool IsExpression_v = IsExpression<T>::value;
71	/*--------------------------------------------------------------------------------------------------------------------*/
72	template <std::size_t N, typename T, typename L = void>
73	struct LocalVar {
74	    static_assert(!std::is_reference_v<T>, "[ERROR]: [Atvoss][Expression] A LocalVar must not be a reference");
75	    using Type = T;
76	    using RetType = std::decay_t<T>;
77	    using TensorType = RetType;
78	    using Like = L;
79	    static constexpr std::size_t number = N;
80	
81	    template <typename V>
82	    constexpr auto operator=(Expression<V>)
83	    {
84	        static_assert(
85	            Util::AlwaysFalse_v<V>, "[ERROR]: [Atvoss][Expression] Please use Expression<LocalVar> for assignment");
86	    }
87	};
88	
89	template <typename T>
90	struct IsLocalVar : std::false_type {};
91	
92	template <std::size_t N, typename T, typename L>
93	struct IsLocalVar<LocalVar<N, T, L>> : std::true_type {};
94	
95	template <typename T>
96	inline constexpr bool IsLocalVar_v = IsLocalVar<T>::value;
97	/*--------------------------------------------------------------------------------------------------------------------*/
98	template <std::size_t N, typename T, ParamUsage U = ParamUsage::IN, std::size_t RN = N>
99	struct Param {
100	    using Type = T;
101	    using RetType = std::decay_t<T>;
102	    using TensorType = RetType;
103	    static constexpr std::size_t number = N;
104	    // for IN_OUT scenario. Two `Param`s point to the same GM
105	    static constexpr std::size_t inplaceNumber = RN;
106	    static constexpr ParamUsage usage = U;
107	
108	    template <typename W>
109	    constexpr auto operator=(Expression<W>)
110	    {
111	        static_assert(
112	            Util::AlwaysFalse_v<W>, "[ERROR]: [Atvoss][Expression] Please use Expression<Param> for assignment");
113	    }
114	};
